<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $closure = function() use (&$closure) { \Carbon\Carbon::setTestNow(null); $tz = \App\Services\NtpTimeService::getTimezone(); $unix = \App\Services\NtpTimeService::getCurrentUnixTimestamp(); $now = new \Illuminate\Support\Carbon(date("Y-m-d H:i:s.u", $unix), $tz); \Carbon\Carbon::setTestNow($closure); return $now; }; \Carbon\Carbon::setTestNow($closure); echo "CarbonImmutable: " . \Carbon\CarbonImmutable::now() . "\n"; ?>
